package com.teamchat.realtime.websocket;

import com.teamchat.realtime.dto.TypingEventDto;
import com.teamchat.realtime.service.TeamMembershipService;
import org.springframework.messaging.handler.annotation.DestinationVariable;
import org.springframework.messaging.handler.annotation.MessageMapping;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.messaging.simp.SimpMessagingTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Controller;
import java.security.Principal;

@Controller
public class TeamTypingWebSocketController {

    private final SimpMessagingTemplate messagingTemplate;
    private final TeamMembershipService membershipService;

    public TeamTypingWebSocketController(SimpMessagingTemplate messagingTemplate, TeamMembershipService membershipService) {
        this.messagingTemplate = messagingTemplate;
        this.membershipService = membershipService;
    }

    @MessageMapping("/team/{teamId}/typing-indicator")
    public void broadcastTyping(
            @DestinationVariable Long teamId,
            @Payload TypingEventDto event,
            Principal principal) {
        if (!membershipService.isMember(principal.getName(), teamId)) {
            throw new AccessDeniedException("Cannot send typing events to a team the user does not belong to");
        }
        messagingTemplate.convertAndSend("/topic/team/" + teamId + "/typing", event);
    }
}
